package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.mapper.IdentityKey;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;

/**
 * Rejects a create-owner request that duplicates an existing owner. Two rules are folded here,
 * both keyed off the now-computed {@code householdId} (SHA-256 of last name + postcode, see
 * {@link AssignHousehold}):
 *
 * <ol>
 * <li><b>Identity match</b> — the derived {@code identityKey}
 * ({@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}, see
 * {@link IdentityKey}) exactly equals an existing owner's. This expresses the former telephone
 * and email duplicate checks. It fires regardless of {@code sharesHousehold}, so a full
 * duplicate that opts in is still a 409.</li>
 * <li><b>Household duplicate</b> — an existing owner shares this owner's {@code householdId}
 * (i.e. the same last name and postcode). Because the household is keyed on those fields, a
 * second such owner is the same household and is rejected — <em>unless</em> the request sets
 * {@code sharesHousehold}, which admits it as a declared household member.</li>
 * </ol>
 *
 * <p>Runs after {@link AssignHousehold} (so the built owner's householdId is settled) and
 * before {@link CheckPossibleDuplicate}/{@link SaveOwner} (so the new owner is not yet among
 * {@code findAll()}). On a match raises {@link DuplicateIdentityException} (409).
 */
public class CheckOwnerIdentityUnique {

    public void service(@Val Owner built, @Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateIdentityException {
        String identityKey = IdentityKey.of(built);
        boolean sharesHousehold = Boolean.TRUE.equals(request.getSharesHousehold());
        String householdId = built.getHouseholdId();
        for (Owner existing : ownerRepository.findAll()) {
            if (identityKey.equals(IdentityKey.of(existing))) {
                throw new DuplicateIdentityException(identityKey);
            }
            if (!sharesHousehold && householdId != null
                    && householdId.equals(existing.getHouseholdId())) {
                throw new DuplicateIdentityException(identityKey);
            }
        }
    }
}
=== CheckPossibleDuplicate ===
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Flags a soft (non-hard) duplicate: a <em>suspected</em>, undeclared duplicate across
 * households. By the time this step runs the request has already passed
 * {@link CheckOwnerIdentityUnique}, so it is neither a full-identity nor an (undeclared)
 * household duplicate. This step records a weaker signal: an existing owner that shares this
 * owner's {@code lastName} (compared case-insensitively) and {@code postcode} but has a
 * <em>different</em> telephone <em>and a different {@code householdId}</em>. Such an owner is
 * still created, but with {@code possibleDuplicate = true} and {@code possibleDuplicateOf} set
 * to the matching owner's id (the lowest matching id when several match). When nothing matches,
 * {@code possibleDuplicate} is {@code false} and {@code possibleDuplicateOf} stays absent.
 *
 * <p>Because {@code householdId} is now computed from last name and postcode, any owner that
 * shares both with an existing one is in the <em>same</em> household. Such a pairing is handled
 * by the household-duplicate block (rejected, or admitted as a declared member): a declared
 * member is not a suspected duplicate, so the same-household exclusion keeps it unflagged.
 *
 * <p>Runs after {@link CheckOwnerIdentityUnique} and before {@link SaveOwner} (so the new
 * owner is not yet among {@code findAll()} and cannot match itself), mutating the built
 * {@link Owner} in place.
 */
public class CheckPossibleDuplicate {

    public void service(@Val Owner built, OwnerRepository ownerRepository) {
        Integer matchId = null;
        for (Owner existing : ownerRepository.findAll()) {
            if (sameLastName(built, existing) && samePostcode(built, existing)
                    && differentTelephone(built, existing) && differentHousehold(built, existing)) {
                Integer id = existing.getId();
                if (id != null && (matchId == null || id < matchId)) {
                    matchId = id;
                }
            }
        }
        built.setPossibleDuplicate(matchId != null);
        built.setPossibleDuplicateOf(matchId);
    }

    private static boolean sameLastName(Owner a, Owner b) {
        return normalize(a.getLastName()).equals(normalize(b.getLastName()));
    }

    private static boolean samePostcode(Owner a, Owner b) {
        String pa = a.getPostcode();
        String pb = b.getPostcode();
        return pa != null && !pa.isBlank() && pa.equals(pb);
    }

    private static boolean differentTelephone(Owner a, Owner b) {
        String ta = a.getTelephone();
        String tb = b.getTelephone();
        return ta == null ? tb != null : !ta.equals(tb);
    }

    /** A declared household member (same computed householdId) is not a suspected duplicate. */
    private static boolean differentHousehold(Owner a, Owner b) {
        String ha = a.getHouseholdId();
        return ha == null || !ha.equals(b.getHouseholdId());
    }

    private static String normalize(String value) {
        return value == null ? "" : value.trim().toLowerCase();
    }
}
=== CountNamesakes ===
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Records the owner's {@code namesakeCount}: the number of existing owners that, at the
 * moment this owner is created, already share the same first name and last name compared
 * case-insensitively (whitespace trimmed). Zero when the name is unique. Runs after
 * {@link BuildOwner} (so the entity, hence its names, exists) and before {@link SaveOwner}
 * (so the new owner is not counted among its own namesakes), and mutates the built
 * {@link Owner} in place.
 */
public class CountNamesakes {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String firstName = normalize(owner.getFirstName());
        String lastName = normalize(owner.getLastName());
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (firstName.equals(normalize(existing.getFirstName()))
                    && lastName.equals(normalize(existing.getLastName()))) {
                count++;
            }
        }
        owner.setNamesakeCount(count);
    }

    /** Lower-case and trim, treating null as empty, for case-insensitive comparison. */
    private static String normalize(String value) {
        return value == null ? "" : value.trim().toLowerCase();
    }
}
=== BuildOwner ===
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

public class BuildOwner {

    public void service(@Val OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built) {
        Owner owner = ownerMapper.toOwner(request);
        // The effective registration date (supplied or defaulted to today) must fall on a
        // business day; a weekend rolls forward to the next Monday.
        owner.setRegistrationDate(BusinessDay.effective(request));
        built.set(owner);
    }
}

